import{_ as a,o as t,c as o,a5 as i}from"./chunks/framework.DOB-AMqW.js";const p=JSON.parse('{"title":"Life Leaf Data Collection","description":"Official data-collection information for Life Leaf.","frontmatter":{"title":"Life Leaf Data Collection","description":"Official data-collection information for Life Leaf.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/life-leaf.md","filePath":"data-collection/life-leaf.md"}'),n={name:"data-collection/life-leaf.md"};function l(r,e,s,c,d,f){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="life-leaf-data-collection" tabindex="-1">Life Leaf Data Collection <a class="header-anchor" href="#life-leaf-data-collection" aria-label="Permalink to &quot;Life Leaf Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 23, 2026</p><h2 id="data-stored-locally" tabindex="-1">Data stored locally <a class="header-anchor" href="#data-stored-locally" aria-label="Permalink to &quot;Data stored locally&quot;">​</a></h2><p>Life Leaf can store diary titles and rich-text content, dates and times, moods, tags, favourites, archive or trash status, optional places and weather notes, attachments, reminder choices, and preferences on your device. Optional PIN verification data is stored as a salted PBKDF2-SHA-256 verifier. Android handles biometric verification without giving the app biometric templates.</p><h2 id="optional-local-notifications" tabindex="-1">Optional local notifications <a class="header-anchor" href="#optional-local-notifications" aria-label="Permalink to &quot;Optional local notifications&quot;">​</a></h2><p>When you enable a reminder, Life Leaf requests notification permission when required and schedules the selected reminder locally. Schedules can include the chosen time, selected weekdays, and reminder category. Notification wording is generic and does not reveal diary content. The schedule is not sent to the developer.</p><h2 id="user-initiated-files-and-sharing" tabindex="-1">User-initiated files and sharing <a class="header-anchor" href="#user-initiated-files-and-sharing" aria-label="Permalink to &quot;User-initiated files and sharing&quot;">​</a></h2><p>Backups, restores, attachments, and content shared into Life Leaf are processed only after you choose the relevant file or sharing action. Shared text or an image opens as an unsaved draft. An external destination receives a backup or file only when you choose to save or share it there.</p><h2 id="data-collected-by-the-developer" tabindex="-1">Data collected by the developer <a class="header-anchor" href="#data-collected-by-the-developer" aria-label="Permalink to &quot;Data collected by the developer&quot;">​</a></h2><p>Life Leaf has no account, developer-operated cloud, analytics, advertising, crash-reporting service, or tracker. The developer does not receive diary data, attachments, reminders, security credentials, or usage telemetry. A support email contains only what you choose to send.</p><h2 id="google-play-data-safety-context" tabindex="-1">Google Play Data safety context <a class="header-anchor" href="#google-play-data-safety-context" aria-label="Permalink to &quot;Google Play Data safety context&quot;">​</a></h2><p>App information and optional reminder processing stay on the device and are not transmitted to the developer. Google Play generally defines collection as transmission off the device. The Play Console declaration must still be reviewed for each released app version and for user-initiated transfers to external destinations.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',14)])])}const u=a(n,[["render",l]]);export{p as __pageData,u as default};
